// 取得訂單輸入資料
const body = $input.first().json.body || {};
const customer = body.customer_name || '訪客';
const isVip = body.is_vip === true;
const items = Array.isArray(body.items) ? body.items : [];

// 計算商品小計
let subtotal = 0;
const processedItems = items.map(item => {
  const itemTotal = (item.price || 0) * (item.quantity || 1);
  subtotal += itemTotal;
  return {
    name: item.name,
    price: item.price,
    quantity: item.quantity || 1,
    total: itemTotal
  };
});

// 計算 VIP 折扣 (VIP 享 9 折)
const discountRate = isVip ? 0.1 : 0;
const discountAmount = Math.round(subtotal * discountRate);

// 運費規則 (滿 1000 免運，否則 60 元)
const shippingFee = subtotal >= 1000 || subtotal === 0 ? 0 : 60;
const finalAmount = subtotal - discountAmount + shippingFee;

return [{
  json: {
    order_id: 'ORD-' + Date.now(),
    customer_name: customer,
    is_vip: isVip,
    item_count: items.length,
    items: processedItems,
    subtotal: subtotal,
    discount_amount: discountAmount,
    shipping_fee: shippingFee,
    final_amount: finalAmount,
    status: 'confirmed',
    created_at: new Date().toISOString()
  }
}];
